<template>
  <div v-if="show && reservation" class="overlay" @click.self="$emit('close')">
    <section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title">
      <header class="sheet-head"><div><span class="eyebrow">FICHA OPERATIVA · SAN GIL</span><h2 id="sheet-title">{{ reservation.servicioNombre || reservation.servicio?.nombre || 'Reserva de aventura' }}</h2></div><button class="close" aria-label="Cerrar ficha" @click="$emit('close')">&times;</button></header>
      <div class="sheet-grid">
        <section class="info-card customer"><h3>Cliente</h3><strong>{{ reservation.clienteNombre || reservation.usuario?.nombre || reservation.clienteSnapshot?.nombre || 'Cliente' }}</strong><span>{{ reservation.clienteEmail || reservation.usuario?.email || reservation.clienteSnapshot?.email || 'Sin correo' }}</span><span>{{ reservation.clienteTelefono || reservation.usuario?.telefono || reservation.clienteSnapshot?.telefono || 'Sin teléfono' }}</span></section>
        <section class="info-card"><h3>Aventura</h3><div class="pair"><span>Fecha</span><strong>{{ dateOnly }}</strong></div><div class="pair"><span>Hora</span><strong>{{ timeOnly }}</strong></div><div class="pair"><span>Participantes</span><strong>{{ reservation.participantes || 1 }}</strong></div><div class="pair"><span>Nivel</span><strong>{{ reservation.nivelExperiencia || 'Principiante' }}</strong></div></section>
        <section class="info-card"><h3>Pago y operación</h3><div class="pair"><span>Estado de reserva</span><strong class="state" :class="`state-${reservation.estado}`">{{ stateLabel }}</strong></div><div class="pair"><span>Estado del pago</span><strong :class="paymentReceived ? 'paid' : 'unpaid'">{{ paymentReceived ? 'Pago aprobado' : 'Pendiente de pago' }}</strong></div><div class="pair"><span>Total COP</span><strong>{{ currency(reservation.precioTotal) }}</strong></div><div class="pair"><span>Método de pago</span><strong>{{ paymentLabel }}</strong></div><div class="pair"><span>Código de ticket QR</span><strong>{{ reservation.ticketCode || 'Aún no emitido' }}</strong></div></section>
        <section class="info-card wide"><h3>Notas para el guía</h3><p>{{ reservation.observaciones || 'Sin notas adicionales.' }}</p></section>
        <section class="info-card wide meetup"><div><h3>Punto de encuentro</h3><p>{{ reservation.puntoEncuentro || 'Base de operaciones en San Gil. Confirma con el guía el punto exacto antes de salir.' }}</p></div><div v-if="reservation.ticketCode" class="qr"><img :src="qrUrl" alt="QR del ticket de reserva"><small>Validación del ticket</small></div></section>
      </div>
      <footer><button class="secondary" @click="$emit('close')">Cerrar</button><button class="secondary" @click="download"><svg viewBox="0 0 24 24"><path d="M12 3v12m-5-5 5 5 5-5M5 20h14"/></svg>Descargar ficha</button><button class="primary" @click="print"><svg viewBox="0 0 24 24"><path d="M7 8V3h10v5m-10 9H5a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2m-10-3h10v7H7z"/></svg>Imprimir ficha</button></footer>
    </section>
  </div>
</template>

<script setup>
import { computed } from 'vue'
import { formatCOP } from '../utils/currency'
const props = defineProps({ show: Boolean, reservation: { type: Object, default: null } })
defineEmits(['close'])
const code = computed(() => props.reservation?.ticketCode || `RESERVA-${props.reservation?._id || props.reservation?.id || ''}`)
const qrUrl = computed(() => `https://api.qrserver.com/v1/create-qr-code/?size=160x160&margin=6&data=${encodeURIComponent(JSON.stringify({ codigo: code.value, reserva: String(props.reservation?._id || props.reservation?.id || '') }))}`)
const date = computed(() => new Date(props.reservation?.fechaHora || props.reservation?.fecha))
const dateOnly = computed(() => Number.isNaN(date.value.getTime()) ? 'Por confirmar' : date.value.toLocaleDateString('es-CO', { dateStyle: 'long' }))
const timeOnly = computed(() => Number.isNaN(date.value.getTime()) ? 'Por confirmar' : date.value.toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' }))
const stateLabel = computed(() => ({ pendiente: 'Pendiente', confirmada: 'Confirmada', completada: 'Completada', cancelada: 'Cancelada' })[props.reservation?.estado] || 'Pendiente')
const paymentLabel = computed(() => ({ tarjeta: 'Tarjeta · simulado', nequi: 'Nequi · simulado', daviplata: 'DaviPlata · simulado', pse: 'PSE · simulado', efectivo: 'Efectivo · oficina', transferencia: 'Transferencia' })[props.reservation?.metodoPago] || 'Sin pago')
const paymentReceived = computed(() => props.reservation?.estadoPago === 'aprobado' || Boolean(props.reservation?.pagadoEn))
function currency(value) { return formatCOP(value) }
function esc(value) { return String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]) }
function html() {
  const r = props.reservation
  const rows = [['Cliente', r.clienteNombre || r.usuario?.nombre || r.clienteSnapshot?.nombre], ['Correo', r.clienteEmail || r.usuario?.email || r.clienteSnapshot?.email], ['Teléfono', r.clienteTelefono || r.usuario?.telefono || r.clienteSnapshot?.telefono], ['Fecha', `${dateOnly.value} · ${timeOnly.value}`], ['Participantes', r.participantes || 1], ['Nivel', r.nivelExperiencia], ['Estado del pago', paymentReceived.value ? 'Pago aprobado' : 'Pendiente de pago'], ['Total', currency(r.precioTotal)], ['Método de pago', paymentLabel.value], ['Ticket', r.ticketCode || 'Pendiente'], ['Notas', r.observaciones || 'Sin notas'], ['Encuentro', r.puntoEncuentro || 'Base de operaciones en San Gil; confirmar punto exacto con el guía.']]
  return `<!doctype html><html lang="es"><meta charset="utf-8"><title>Ficha ${esc(code.value)}</title><style>body{font:15px Arial,sans-serif;color:#172033;background:#f1f5f9;margin:0;padding:28px}.sheet{max-width:760px;margin:auto;padding:28px;background:#fff;border:1px solid #cbd5e1;border-radius:14px}h1{font-size:24px}.code{color:#4338ca;font-weight:bold}.row{display:grid;grid-template-columns:130px 1fr;gap:14px;padding:10px 0;border-top:1px solid #e2e8f0}.label{color:#64748b}.qr{float:right;width:150px}</style><article class="sheet"><p>FICHA OPERATIVA · SAN GIL</p><h1>${esc(r.servicioNombre || r.servicio?.nombre || 'Reserva de aventura')}</h1><p class="code">${esc(code.value)} · ${esc(stateLabel.value)}</p>${r.ticketCode ? `<img class="qr" src="${esc(qrUrl.value)}">` : ''}${rows.map(([label,value])=>`<div class="row"><span class="label">${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}</article></html>`
}
function download() { const url = URL.createObjectURL(new Blob([html()], { type: 'text/html;charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = `ficha-${String(code.value).replace(/[^A-Za-z0-9-]/g, '')}.html`; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
function print() { const page = window.open('', '_blank', 'width=900,height=700'); if (!page) return; page.document.write(html()); page.document.close(); page.onload = () => page.print() }
</script>

<style scoped>
.overlay{position:fixed;inset:0;z-index:145;display:grid;place-items:center;padding:16px;background:#020617d1;backdrop-filter:blur(12px)}.sheet{width:min(100%,760px);max-height:calc(100vh - 32px);overflow:auto;padding:24px;border:1px solid #475569;border-radius:20px;background:linear-gradient(145deg,#172235,#0b1120);box-shadow:0 28px 90px #020617d1;color:#e2e8f0}.sheet-head{display:flex;justify-content:space-between;gap:15px;margin-bottom:20px}.eyebrow{color:#a5b4fc;font-size:9px;font-weight:800;letter-spacing:.15em}.sheet h2{margin:7px 0;color:#f8fafc;font-size:22px}.close{border:0;background:none;color:#cbd5e1;font-size:26px;cursor:pointer}.sheet-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.info-card{min-width:0;padding:14px;border:1px solid #334155;border-radius:12px;background:#0b112080}.info-card h3{margin:0 0 10px;color:#c7d2fe;font-size:12px;font-weight:800}.customer{display:grid;align-content:start;gap:7px}.customer>strong{color:#f8fafc;font-size:15px}.customer>span,.info-card p{margin:0;color:#aebbd0;font-size:12px;line-height:1.5;overflow-wrap:anywhere}.pair{display:flex;justify-content:space-between;gap:12px;padding:7px 0;border-top:1px solid #293548}.pair span{color:#94a3b8;font-size:11px}.pair strong{color:#e2e8f0;font-size:11px;text-align:right}.pair .state-pendiente{color:#fcd34d}.pair .state-confirmada{color:#86efac}.pair .state-completada{color:#93c5fd}.pair .state-cancelada{color:#fda4af}.pair .paid{color:#86efac}.pair .unpaid{color:#fcd34d}.wide{grid-column:1/-1}.meetup{display:flex;justify-content:space-between;align-items:center;gap:16px}.meetup>div:first-child{max-width:70%}.qr{display:grid;justify-items:center;padding:7px;border-radius:9px;background:#fff}.qr img{width:100px;height:100px}.qr small{padding-top:3px;color:#475569;font-size:9px}footer{display:flex;justify-content:flex-end;gap:8px;margin-top:15px;padding-top:14px;border-top:1px solid #334155}.secondary,.primary{display:inline-flex;align-items:center;gap:7px;min-height:39px;padding:9px 12px;border-radius:9px;font-size:11px;font-weight:750;cursor:pointer}.secondary{border:1px solid #475569;background:#1e293b;color:#dbe3ee}.primary{border:0;background:#4f46e5;color:#fff}.primary:hover{background:#6366f1}.primary svg,.secondary svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}@media(max-width:560px){.sheet{padding:18px}.sheet-grid{grid-template-columns:1fr}.wide{grid-column:auto}.meetup{align-items:flex-start}.meetup>div:first-child{max-width:none}footer{flex-wrap:wrap}.secondary,.primary{flex:1 1 40%}}
</style>
